reference_solution:
def getIntersectionNode(headA, headB):
    a, b = headA, headB
    while a is not b:
        a = a.next if a else headB
        b = b.next if b else headA
    return a

brute_force_solution:
def getIntersectionNode(headA, headB):
    seen = set()
    while headA:
        seen.add(id(headA))
        headA = headA.next
    while headB:
        if id(headB) in seen:
            return headB
        headB = headB.next
    return None

